#!/usr/bin/env bash
# Regenerates v1/pairing.txt, the test vector for the hashes and tags of
# docs/protocol.md: fingerprints, the exporter context, the pairing and
# presence tags, the beacon, the QR proofs and the SAS. The inputs are
# fixed below. The two exporter values are inputs too, because TLS derives
# them; this vector checks everything built on top of them.
# Needs openssl and xxd.
set -euo pipefail
cd "$(dirname "$0")"

# Hex of an ASCII string.
text() { printf '%s' "$1" | xxd -p -c 1000; }
# Hex of the bytes from $1 to $2 - 1, such as "00010203" for 0 4.
run() { local i out=""; for ((i = $1; i < $2; i++)); do out+=$(printf '%02x' "$i"); done; echo "$out"; }
sha256() { xxd -r -p <<<"$1" | openssl dgst -sha256 -binary | xxd -p -c 1000; }
# HMAC-SHA256 with hex key $1 over hex message $2.
hmac() { xxd -r -p <<<"$2" | openssl dgst -sha256 -mac HMAC -macopt "hexkey:$1" -binary | xxd -p -c 1000; }
b64url() { xxd -r -p <<<"$1" | base64 -w0 | tr '+/' '-_' | tr -d '='; }

# Inputs. The SPKIs are DER SubjectPublicKeyInfo of two P-256 keys.
spki_desktop=3059301306072a8648ce3d020106082a8648ce3d0301070342000400ab45cc89eb45ca1cf15c54f60c467db01aee2ebf6b509dc0233c93d77c09432d3d4d19da5b52e1c6c7d35a48eee28b32dfaed888900298b800f78188c576cc
spki_phone=3059301306072a8648ce3d020106082a8648ce3d0301070342000476f274b2fd60b956b365c84586618ec2574478eb65582dedd3ef14a20232529540fd8669c40fb72670fb1a52c39778b947d5238ed3744d1ce0b527844da3f7d1
secret=$(run 0 16)
ekm_pair=$(run 64 96)
ekm_sas=$(run 96 128)
n_p=$(run 128 160)
n_d=$(run 160 192)
presence_key=$(run 192 224)
presence_nonce=$(run 224 232)
beacon_port=27380
beacon_time=1793318400
beacon_nonce=$(run 240 248)
bt_address=0c1a2b3c4d5e

# Derived values, in the order docs/protocol.md introduces them.
fp_desktop=$(sha256 "$spki_desktop")
fp_phone=$(sha256 "$spki_phone")
exporter_context=$fp_desktop$fp_phone
presence_tag=$(hmac "$presence_key" "$(text l2l-presence-v1)$presence_nonce" | cut -c1-16)
pairing_tag=$(hmac "$secret" "$(text l2l-pairing-tag-v1)" | cut -c1-16)
txt_n=$(b64url "$presence_nonce")
txt_t=$(b64url "$presence_tag")
txt_q=$(b64url "$pairing_tag")
beacon_head=$(text L2LB)0100$(printf '%04x%016x' "$beacon_port" "$beacon_time")$beacon_nonce
beacon=$beacon_head$(hmac "$presence_key" "$(text l2l-beacon-v1)$beacon_head" | cut -c1-32)
qr_uri="link2linux://pair?v=1&f=$(b64url "$fp_desktop")&s=$(b64url "$secret")"
qr_uri+="&n=B%C3%BCro%20workstation&a=192.168.1.20,fd00::20&b=${bt_address^^}"
proof_desktop=$(hmac "$secret" "$(text l2l-pair-v1)01$ekm_pair")
proof_phone=$(hmac "$secret" "$(text l2l-pair-v1)02$ekm_pair")
sas_commitment=$(sha256 "$(text l2l-sas-commit-v1)$ekm_sas$n_p")
sas_hmac=$(hmac "$ekm_sas" "$(text l2l-sas-v1)$n_d$n_p")
sas_code=$(printf '%06d' $((16#${sas_hmac:0:8} % 1000000)))

{
  echo "# Pairing and discovery test vector; see README.md. Generated by"
  echo "# pairing.sh. Lines are \"name = value\"; byte strings are hex."
  echo
  echo "# Inputs"
  for name in spki_desktop spki_phone secret ekm_pair ekm_sas n_p n_d \
    presence_key presence_nonce beacon_port beacon_time beacon_nonce bt_address; do
    echo "$name = ${!name}"
  done
  echo
  echo "# Outputs"
  for name in fp_desktop fp_phone exporter_context presence_tag pairing_tag \
    txt_n txt_t txt_q beacon qr_uri proof_desktop proof_phone sas_commitment \
    sas_hmac sas_code; do
    echo "$name = ${!name}"
  done
} > v1/pairing.txt
echo "wrote v1/pairing.txt"
